package cli

import (
	"encoding/json"
	"fmt"
	"sort"

	"github.com/spf13/cobra"
)

type neighborOut struct {
	RC       string         `json:"rc"`
	Distance float64        `json:"distance_m"`
	Data     map[string]any `json:"data,omitempty"`
}

func newNeighborsCmd(flags *rootFlags) *cobra.Command {
	var (
		radius float64
		fetch  bool
		srs    string
	)
	cmd := &cobra.Command{
		Use:   "neighbors <RC>",
		Short: "Devuelve las RCs vecinas dentro de un radio (default 50 m), opcionalmente con sus datos DNPRC",
		Long: "Combina CPMRC (RC→coords) + RCCOOR_Distancia para devolver las parcelas vecinas, ordenadas por\n" +
			"distancia. Con --fetch hace un DNPRC adicional por cada vecina para devolver superficie/uso/año.\n" +
			"Útil para expedientes de segregación/agrupación donde necesitas las parcelas colindantes.",
		Example: "  catastro-pp-cli neighbors 0545206VK4704F0001RE --radius 50 --fetch --json",
		Annotations: map[string]string{
			"mcp:read-only": "true",
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			if len(args) == 0 {
				return cmd.Help()
			}
			rc := args[0]
			if dryRunOK(flags) {
				fmt.Fprintf(cmd.OutOrStdout(),
					`{"would_call":"CPMRC+RCCOOR_Distancia","rc":%q,"radius_m":%g}`+"\n",
					rc, radius)
				return nil
			}

			// Step 1: RC → coords via CPMRC
			coordsData, err := coordenadasGET(flags.timeout, "Consulta_CPMRC", map[string]string{
				"Provincia": "",
				"Municipio": "",
				"SRS":       srs,
				"RC":        rc,
			})
			if err != nil {
				return fmt.Errorf("CPMRC: %w", err)
			}
			var coords struct {
				Coordinates []struct {
					RC  string `json:"rc"`
					Lon string `json:"lon"`
					Lat string `json:"lat"`
				} `json:"coordinates"`
			}
			if err := json.Unmarshal(coordsData, &coords); err != nil {
				return fmt.Errorf("parse CPMRC response: %w", err)
			}
			if len(coords.Coordinates) == 0 {
				return fmt.Errorf("RC %s not found or no coords returned", rc)
			}
			lon, lat := coords.Coordinates[0].Lon, coords.Coordinates[0].Lat

			// Step 2: coords → nearby RCs via RCCOOR_Distancia
			nearbyData, err := coordenadasGET(flags.timeout, "Consulta_RCCOOR_Distancia", map[string]string{
				"SRS":          srs,
				"Coordenada_X": lon,
				"Coordenada_Y": lat,
			})
			if err != nil {
				return fmt.Errorf("RCCOOR_Distancia: %w", err)
			}
			var nearby struct {
				References []struct {
					RC       string  `json:"rc"`
					Distance float64 `json:"distance_m"`
				} `json:"references"`
			}
			if err := json.Unmarshal(nearbyData, &nearby); err != nil {
				return fmt.Errorf("parse RCCOOR_Distancia response: %w", err)
			}

			// Filter by radius and exclude the center RC
			out := []neighborOut{}
			for _, n := range nearby.References {
				if n.RC == rc {
					continue
				}
				if radius > 0 && n.Distance > radius {
					continue
				}
				out = append(out, neighborOut{RC: n.RC, Distance: n.Distance})
			}
			sort.Slice(out, func(i, j int) bool { return out[i].Distance < out[j].Distance })

			// Step 3 (optional): fetch DNPRC for each
			if fetch {
				c, err := flags.newClient()
				if err == nil {
					for i := range out {
						data, err := c.Get("/COVCCallejero.svc/json/Consulta_DNPRC", map[string]string{"RefCat": out[i].RC})
						if err == nil {
							out[i].Data = parseProperty(data)
						}
					}
				}
			}

			return printJSONFiltered(cmd.OutOrStdout(), mustMarshal(out), flags)
		},
	}
	cmd.Flags().Float64Var(&radius, "radius", 50.0, "Radio en metros (default 50)")
	cmd.Flags().BoolVar(&fetch, "fetch", false, "Llamar a DNPRC para cada vecina y enriquecer con sus datos")
	cmd.Flags().StringVar(&srs, "srs", "EPSG:4326", "SRS para el centroide intermedio")
	return cmd
}

func mustMarshal(v any) json.RawMessage {
	b, _ := json.Marshal(v)
	return b
}
